# aplicar-correos-marca-panel.ps1 - Ojo Guard MS: los mails salen con la imagen nueva y los links con ms.ojoguard.app.
# Luciano (22/10/2026): "corregir los envios de los mails con el nuevo formato de imagen".
#  - Todos los mails (codigo de ingreso, avisos de seguridad, "Estas bien?", "Llegaste bien?", SOS, referentes, Modo Guardian) salen con franja azul marino + logo nuevo (ojo dorado y "Ojo Guard") y el cuerpo en blanco, texto azul oscuro, botones azules.
#  - El mail del codigo de ingreso pasa a tener el codigo grande en una caja.
#  - Los links de los mails y de los SMS (y la direccion del logo) pasan de ojo-guard-ms-api.bickluciano.workers.dev a ms.ojoguard.app.
# No se saca ningun dato ni funcion de los mails: solo cambia el aspecto. Cambia SOLO src\index.ts (respaldo index.ts.bak-correosmarca).
# Va en la carpeta del PANEL (la que tiene wrangler.toml). Al final publica el panel solo.
$ErrorActionPreference = "Continue"
function Ok($t)  { Write-Host ("OK    " + $t) -ForegroundColor Green }
function Mal($t) { Write-Host ("MAL   " + $t) -ForegroundColor Red }
function Avi($t) { Write-Host ("AVISO " + $t) -ForegroundColor Yellow }
$raiz = (Get-Location).Path
function Contar([string]$donde, [string]$que) {
    if ([string]::IsNullOrEmpty($que)) { return 0 }
    $n = 0; $i = 0
    while ($true) { $i = $donde.IndexOf($que, $i, [System.StringComparison]::Ordinal); if ($i -lt 0) { break }; $n = $n + 1; $i = $i + $que.Length }
    return $n
}
function Leer([string]$ruta) {
    $bytes = [System.IO.File]::ReadAllBytes($ruta)
    $bom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
    $texto = [System.IO.File]::ReadAllText($ruta, [System.Text.Encoding]::UTF8)
    return @{ texto = $texto; bom = $bom; crlf = $texto.Contains("`r`n") }
}
function Ajustar([string]$t, [bool]$crlf) { $x = ($t -replace "`r`n", "`n"); if ($crlf) { $x = $x -replace "`n", "`r`n" }; return $x }
function Sha([string]$ruta) { return (Get-FileHash -Algorithm SHA256 -LiteralPath $ruta).Hash.ToLower() }

if (-not (Test-Path (Join-Path $raiz "wrangler.toml"))) { Mal "Abri PowerShell en la carpeta del PANEL (la que tiene wrangler.toml), no la de la app."; return }
Ok "Carpeta correcta"
if (-not (Test-Path (Join-Path $raiz "src\index.ts"))) { Mal "No encuentro src\index.ts en esta carpeta."; return }
if ((Contar (Leer (Join-Path $raiz "src\index.ts")).texto 'function conMarcaCorreoNuevo') -ne 0) { Avi "Esto ya estaba aplicado. No toco nada."; return }
$cambios = @(
    @('src\index.ts', 'direccion del panel en mails y SMS (ms.ojoguard.app)', 'const DEFAULT_PANEL_URL = "https://ojo-guard-ms-api.bickluciano.workers.dev/";', 'const DEFAULT_PANEL_URL = "https://ms.ojoguard.app/";'),
    @('src\index.ts', 'mails: se arma con la franja nueva', 'conMarcaCorreo(datos.html, datos.subject)', 'conMarcaCorreoNuevo(datos.html, datos.subject)'),
    @('src\index.ts', 'ruta del logo nuevo', 'if (route === "GET /marca/logo-correo.png") return logoCorreoResponse();', 'if (route === "GET /marca/ojo-guard-correo.png") return logoCorreoNuevoResponse();
      if (route === "GET /marca/logo-correo.png") return logoCorreoResponse();'),
    @('src\index.ts', 'funciones nuevas de los mails', 'export default {', '// Correos con la imagen nueva de Ojo Guard (azul, blanco y dorado). Logo en PNG 588x108 (los correos no muestran SVG).
const LOGO_CORREO_NUEVO_B64 = "";
function logoCorreoNuevoResponse() {
  const bytes = Uint8Array.from(atob(LOGO_CORREO_NUEVO_B64), (c) => c.charCodeAt(0));
  return new Response(bytes, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400", "x-content-type-options": "nosniff" } });
}
// Los cuerpos de los correos estan escritos con la paleta oscura de antes; aca se pasan a la paleta clara de la marca.
function claroCorreo(html: string) {
  const mapa: Array<[string, string]> = [
    ["background:#0c0d0f;color:#f6f6f2;padding:28px;border-radius:20px", "background:#ffffff;color:#14213D;padding:28px;border:1px solid #E3E7F1;border-top:0;border-radius:0 0 16px 16px"],
    ["max-width:560px", "max-width:620px"],
    ["background:#d9b24c;color:#111", "background:#1F4FD1;color:#ffffff"],
    ["background:#201c12;border:1px solid #56461d;border-radius:12px;color:#e4d7ad", "background:#FFF3D6;border:1px solid #F0D79A;border-radius:12px;color:#7A5200"],
    ["<strong style=\"color:#fff\">", "<strong style=\"color:#14213D\">"],
    ["background:#0c0d0f", "background:#ffffff"],
    ["color:#f6f6f2", "color:#14213D"],
    ["color:#d2d2ce", "color:#3E4A6B"],
    ["color:#8f8d85", "color:#5B6580"],
    ["color:#8d8d88", "color:#5B6580"],
    ["color:#f4c64e", "color:#7A5200"],
    ["color:#ff8a7a", "color:#C62828"],
    ["color:#d9b24c", "color:#1F4FD1"],
    ["ojo guard &middot; modo cautela", "Ojo Guard &middot; modo cautela"],
  ];
  let r = html;
  for (const [viejo, nuevo] of mapa) r = r.split(viejo).join(nuevo);
  return r;
}
// Arriba: franja azul marino con el logo y, al lado, que se pidio o que paso y de que equipo. Abajo: el cuerpo en blanco.
function conMarcaCorreoNuevo(html: string, asunto?: unknown) {
  if (html.includes("data-og-marca")) return html;
  const logo = `${DEFAULT_PANEL_URL}marca/ojo-guard-correo.png`;
  let titulo = String(asunto ?? "").replace(/^(Aviso de seguridad|Alerta de seguridad|Ojo Guard)\s*[\u00b7\u2014:-]\s*/i, "").trim().slice(0, 90);
  let equipo = ((html.match(/<strong[^>]*>\s*Dispositivo:\s*<\/strong>\s*([^<]{1,60})/) || [])[1] ?? "").trim();
  const corte = titulo.lastIndexOf(" \u00b7 ");
  if (corte > 0) {
    const cola = textoCorreo(titulo.slice(corte + 3).trim());
    if (!equipo) equipo = cola;
    if (cola === equipo) titulo = titulo.slice(0, corte).trim();
  }
  const resumen = titulo || equipo
    ? `<td class="og-res" align="right" style="vertical-align:middle;padding-left:12px;font-family:Arial,sans-serif">${titulo ? `<div style="color:#ffffff;font-size:14px;font-weight:700;line-height:1.3">${textoCorreo(titulo)}</div>` : ""}${equipo ? `<div style="color:#F1D58A;font-size:13px;margin-top:3px">${equipo}</div>` : ""}</td>`
    : "";
  return `<style>@media only screen and (max-width:480px){.og-res,.og-logo{display:block!important;width:auto!important;text-align:left!important}.og-res{padding:12px 0 0!important}}</style><div style="background:#EEF2FB;padding:18px 10px"><div data-og-marca="1" style="max-width:620px;margin:0 auto;padding:16px 22px;background:#0F1A3A;border-radius:16px 16px 0 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr><td class="og-logo" style="vertical-align:middle;width:200px"><img src="${logo}" width="196" height="36" alt="Ojo Guard" style="display:block;border:0;outline:none;text-decoration:none"></td>${resumen}</tr></table></div>${claroCorreo(html)}<div style="max-width:620px;margin:0 auto;padding:14px 22px 0;text-align:center;font-family:Arial,sans-serif;font-size:12px;color:#5B6580">Ojo Guard &middot; soporte@ojoguard.app</div></div>`;
}

export default {'),
    @('src\index.ts', 'mail del codigo: encabezado y codigo grande', '<h1>${code}</h1><p>', '<div style="font-family:Arial,sans-serif;max-width:620px;margin:auto;background:#0c0d0f;color:#f6f6f2;padding:28px;border-radius:20px"><p style="color:#f4c64e;font-size:12px;font-weight:800;letter-spacing:.16em">OJO GUARD &#183; C&#211;DIGO</p><p style="margin:14px 0 18px"><span style="display:inline-block;font-size:34px;font-weight:800;letter-spacing:.3em;padding:14px 20px 14px 26px;border-radius:12px;background:#EEF2FB;color:#14213D">${code}</span></p><p style="color:#d2d2ce;line-height:1.55">'),
    @('src\index.ts', 'mail del codigo: aviso de vencimiento', '<p>Vence en 15 minutos y funciona una sola vez.</p>', '<p style="color:#8f8d85;font-size:13px">Vence en 15 minutos y funciona una sola vez.</p></div>')
)
$descargas = @()

# --- Revisar que todas las anclas esten exactamente una vez, en todos los archivos ---
$archivos = @{}
foreach ($c in $cambios) {
    $ruta = Join-Path $raiz $c[0]
    if (-not (Test-Path $ruta)) { Mal ("No encuentro " + $c[0]); return }
    if (-not $archivos.ContainsKey($c[0])) { $archivos[$c[0]] = Leer $ruta }
}
$ok = $true
foreach ($c in $cambios) {
    $f = $archivos[$c[0]]
    $ancla = Ajustar $c[2] $f.crlf
    $cuantos = Contar $f.texto $ancla
    if ($cuantos -eq 1) { Ok ($c[0] + ": " + $c[1] + ": 1") } else { Mal ($c[0] + ": " + $c[1] + ": " + $cuantos + " (esperaba 1)"); $ok = $false }
}
if (-not $ok) { Mal "Alguna ancla no coincide. No toco nada. Mandame esta pantalla."; return }

# --- Descargar archivos nuevos y verificar que llegaron completos ---
foreach ($d in $descargas) {
    $tmp = (Join-Path $raiz $d[1]) + ".descarga"
    try { Invoke-WebRequest -UseBasicParsing $d[0] -OutFile $tmp } catch { }
    if (-not (Test-Path $tmp) -or (Sha $tmp) -ne $d[2]) {
        foreach ($x in $descargas) { $y = (Join-Path $raiz $x[1]) + ".descarga"; if (Test-Path $y) { Remove-Item -LiteralPath $y -Force } }
        Mal ("No se pudo descargar bien " + $d[1] + ". No toque nada."); return
    }
    Ok ("Descargado y verificado: " + $d[1])
}

# --- Respaldos ---
$tocados = @($archivos.Keys) + @($descargas | ForEach-Object { $_[1] })
foreach ($t in $tocados) {
    $ruta = Join-Path $raiz $t
    if (Test-Path ($ruta + ".bak-correosmarca")) { Mal ("Ya existe " + $t + ".bak-correosmarca. No toco nada."); foreach ($x in $descargas) { $y = (Join-Path $raiz $x[1]) + ".descarga"; if (Test-Path $y) { Remove-Item -LiteralPath $y -Force } }; return }
}
$respaldados = @()
foreach ($t in $tocados) {
    $ruta = Join-Path $raiz $t
    if (Test-Path $ruta) { Copy-Item -LiteralPath $ruta -Destination ($ruta + ".bak-correosmarca"); $respaldados += $t }
}
Ok ("Respaldos creados (.bak-correosmarca): " + ($respaldados -join ", "))

# --- Aplicar ---
$esperado = @{}
foreach ($k in $archivos.Keys) { $esperado[$k] = $archivos[$k].texto.Length }
$nuevos = @{}
foreach ($k in $archivos.Keys) { $nuevos[$k] = $archivos[$k].texto }
foreach ($c in $cambios) {
    $f = $archivos[$c[0]]
    $ancla = Ajustar $c[2] $f.crlf; $reemplazo = Ajustar $c[3] $f.crlf
    $nuevos[$c[0]] = $nuevos[$c[0]].Replace($ancla, $reemplazo)
    $esperado[$c[0]] = $esperado[$c[0]] + ($reemplazo.Length - $ancla.Length)
}
foreach ($k in $archivos.Keys) { [System.IO.File]::WriteAllText((Join-Path $raiz $k), $nuevos[$k], (New-Object System.Text.UTF8Encoding($archivos[$k].bom))) }
foreach ($d in $descargas) { Move-Item -LiteralPath ((Join-Path $raiz $d[1]) + ".descarga") -Destination (Join-Path $raiz $d[1]) -Force }

# --- Verificar ---
$todoBien = $true
function Chk([string]$que, [bool]$cond) { if ($cond) { Ok $que } else { Mal $que; $script:todoBien = $false } }
foreach ($c in $cambios) {
    $v = (Leer (Join-Path $raiz $c[0]))
    Chk ($c[0] + ": " + $c[1] + " aplicado") ((Contar $v.texto (Ajustar $c[3] $v.crlf)) -eq 1)
}
foreach ($k in $archivos.Keys) {
    $largo = (Leer (Join-Path $raiz $k)).texto.Length
    Chk ($k + ": largo " + $largo + " (esperado " + $esperado[$k] + ")") ($largo -eq $esperado[$k])
}
foreach ($d in $descargas) { Chk ($d[1] + ": verificado") ((Sha (Join-Path $raiz $d[1])) -eq $d[2]) }

if (-not $todoBien) {
    Mal "Algo no salio bien. Restauro todo desde los respaldos."
    foreach ($t in $tocados) {
        $ruta = Join-Path $raiz $t
        if ($respaldados -contains $t) { Copy-Item -LiteralPath ($ruta + ".bak-correosmarca") -Destination $ruta -Force }
        elseif (Test-Path $ruta) { Remove-Item -LiteralPath $ruta -Force }
    }
    Mal "Restaurado. Mandame esta pantalla."
    return
}
Write-Host ""
Ok "Archivos listos. Ahora publico el panel..."
& npx.cmd wrangler deploy
if ($LASTEXITCODE -ne 0) { Mal "No se pudo publicar el panel. Mandame esta pantalla."; return }
Write-Host ""
Ok "LISTO: los mails salen con la imagen nueva y los links con ms.ojoguard.app. Pedi un codigo de ingreso para ver el mail nuevo."
Write-Host ""
